decl.add_method(
    sel!(accessibilityDisplayOptionsChanged:),
    accessibility_display_options_changed as extern "C" fn(_, Sel, *mut AnyObject),
);

// Suppress beep on keystrokes with modifier keys.

// The selector observer is window-owned. Defer its callback so a
// preference notification cannot re-enter an in-progress GPUI update.
let workspace: *mut AnyObject = msg_send![class!(NSWorkspace), sharedWorkspace];
let center: *mut AnyObject = msg_send![workspace, notificationCenter];
let _: () = msg_send![center, addObserver: native_view,
    selector: sel!(accessibilityDisplayOptionsChanged:),
    name: ns_string("NSWorkspaceAccessibilityDisplayOptionsDidChangeNotification"),
    object: ptr::null_mut::<AnyObject>()];
let _: () = msg_send![content_view, addSubview: native_view];

let workspace: *mut AnyObject = msg_send![class!(NSWorkspace), sharedWorkspace];
let center: *mut AnyObject = msg_send![workspace, notificationCenter];
let _: () = msg_send![center, removeObserver: this.native_view.as_ptr()];
this.appearance_changed_callback.take();
let _: () = msg_send![this.native_window, setDelegate: ptr::null_mut::<AnyObject>()];

extern "C" fn accessibility_display_options_changed(this: &AnyObject, _: Sel, _: *mut AnyObject) {
    // SAFETY: this is the live GPUIView registered with NSWorkspace above.
    let state = unsafe { get_window_state(this) };
    let executor = state.lock().foreground_executor.clone();
    executor.spawn(async move {
        let callback = state.lock().appearance_changed_callback.take();
        if let Some(mut callback) = callback {
            callback();
            state.lock().appearance_changed_callback = Some(callback);
        }
    }).detach();
}

